INSERT INTO `marine-db`.stakeholders (id, vessel_id, company_id, searched_company_id, name, role, personal_email, professional_email, linkedin_url, status, profile_pic, location, city, region, country, country_code, birth_year, current_employer, current_employer_id, current_employer_domain, current_employer_website, current_employer_linkedin_url, recommended_email, emails_json, phones_json, job_history_json, education_json, skills_json, company_json, others_data, created_by, updated_by, deleted_by, created_at, updated_at, deleted_at) VALUES (224, null, 172, 172, 'Joseph Johansen', 'Senior Crewing Agent', 'josephjjohansen@live.com', null, 'https://www.linkedin.com/in/josephjjohansen', 'progress', 'https://d2gjqh9j26unp0.cloudfront.net/profilepic/8f898189e12a57eaceb510ea7fd03104', 'Virginia Beach, VA, US', 'Virginia Beach', 'VA', 'United States', 'US', 1972, 'US Marine Management Inc', null, null, null, null, 'josephjjohansen@live.com', '[{"type": "personal", "email": "josephjjohansen@live.com", "grade": "A", "smtp_valid": "valid", "last_validation_check": "2025-08-19"}]', '[]', '[{"title": "Senior Crewing Agent", "company": "US Marine Management Inc", "end_date": "Present", "company_id": null, "department": "Operations", "is_current": true, "start_date": "2020-10-01", "description": "Promoted to Senior Crewing Agent 21 months of employment in MAERSK Line Limited.  Partnering with Military Sealift Command, Seafarers\' International Union, American Maritime Officers Union, and several project teams to manage the manning of four ships operated by MLL under the USMMI flag.  Working all routine office business and special projects to achieve MAERSK\'s mission, increase market share, and position MLL/USMMI for the next opportunity.  Daily coordinating travel for Mariners going to or from our ships, reviewing all Mariners\' records for Certification, Training, Medical qualification, and travel documents.  Managing employee reimbursements, performance reviews, recommendations, promotions, and ensuring the best person/position matches.  Direct report to and Primary Assistant to the Director of Operations and Crewing.  On September 20, 2023, USMMI was bought from MLL by Marine Partners, in order to become Jones-Act-compliant for growth in Government Contracting.", "company_name": "US Marine Management Inc", "last_updated": "2025-08-01T08:25:28.476341", "highest_level": "senior", "sub_department": "Logistics", "company_linkedin_url": null}, {"title": "Crewing Agent", "company": "Maersk Line, Limited", "end_date": "2020-09-01", "company_id": 794641, "department": "", "is_current": false, "start_date": "2019-02-01", "description": "Promoted to full Crewing Agent after a month of employment in MAERSK Line Limited.  Partnering with Military Sealift Command, Seafarers\' International Union, American Maritime Officers Union, and several project teams to manage the manning of four ships operated by MLL under the USMMI flag.  Working all routine office business and special projects to achieve MAERSK\'s mission, increase market share, and position MLL/USMMI for the next opportunity.  Daily coordinating travel for Mariners going to or from our ships.  Reviewing all Mariners\' records for Certification, Training, Medical qualification, and travel documents.  Managing I-9 entries in E-Verify, employee reimbursements, performance reviews, recommendations, promotions, and ensuring the best person/position matches.  Learned 4 new HRISs in 2 months time.", "company_name": "Maersk Line, Limited", "last_updated": "2025-08-01T08:25:28.476341", "highest_level": "individual contributor", "sub_department": "", "company_linkedin_url": "https://www.linkedin.com/company/maersk-line-limited"}, {"title": "Assistant Crewing Agent", "company": "Maersk Line, Limited", "end_date": "2019-02-01", "company_id": 794641, "department": "", "is_current": false, "start_date": "2019-01-01", "description": "First job after the Navy!  Sought a position as a Human Resources Specialist to learn how HR works in the civilian business world, to prevent a gap in my professional history, and to support my family.  Coordinated with Seafarers\' International Union, US Coast Guard, and 3 Crewing Agents in support of hundreds of Merchant Mariners on 30 MAERSK ships.  Learned a new HRIS, managed electronic and paper files, drafted letters, managed Excel spreadsheets, and continued to do most of the routine office functions that I did in the Navy.", "company_name": "Maersk Line, Limited", "last_updated": "2025-08-01T08:25:28.476341", "highest_level": "individual contributor", "sub_department": "", "company_linkedin_url": "https://www.linkedin.com/company/maersk-line-limited"}, {"title": "Director of Staff and Director of Human Resources and Security Company Commander", "company": "Coastal Riverine Squadron TWO", "end_date": "2018-12-01", "company_id": null, "department": "", "is_current": false, "start_date": "2017-05-01", "description": "Managed/led eight Sailors in pay, Human Resources, legal actions, the proofing, editing, routing, and mailing of all executive correspondence for the staff of 400 personnel, geographically separated over five overseas detachment sites.  Coordinate/liaison with five Officers in Charge and six fellow Directors of Departments to ensure timeliness and quality in meeting all routine, recurring, and uncommon administrative taskings.  Directed 150 Naval Officers and Enlisted Sailors in 20 water-born and entry-point security teams for port security of international partner nations in the middle-east.  Managed the training, qualification, deployment, promotions, performance review, awards, and follow-on employment assignments of expeditionary Sailors.  Used online databases, locally produced spreadsheets and leadership interactions to find the best fit for the organization and for the individual, while providing each of them with the means and incentive to work on professional development leading to higher positions.  Managed every aspect of deployment preparation of my Sailors, earning the highest certification scores, and making my company the first to certify and complete all administrative preparations for deployment.  Directed the teams that provided maritime and facility security for the busiest operating area of our deployment.  Returned to homeport early to manage the thorough training and qualification of another 155 Sailors new to the organization while also managing the turnover and acceptance of 26 security and patrol boats.  Served as the Commanding Officer\'s representative to his Boss, Commander Coastal Riverine Group TWO, during weekly Update Briefs and other necessary reports and coordination with the parent organization and staff.", "company_name": "Coastal Riverine Squadron TWO", "last_updated": "2025-08-01T08:25:28.476341", "highest_level": "director", "sub_department": "", "company_linkedin_url": null}, {"title": "Director of Human Resources and Executive Assistant", "company": "Commander Carrier Strike Group EIGHT", "end_date": "2017-04-01", "company_id": null, "department": "", "is_current": false, "start_date": "2015-06-01", "description": "Manage Human Resources of the staff of 80 and the Strike Group of 5000 Sailors.  Proof/edit all Executive/Flag level correspondence, policy documents, awards, performance reviews, and messages.  Manage/lead six Sailors in the proofing, editing, routing, and mailing of all Flag correspondence, all pay, Human Resources, and medical readiness of the staff and 20 subordinate units.  Coordinated the efforts and information flow of all 20 command centers of the Admiral\'s Strike group, ensuring constant understanding of the Admiral\'s expectations, and timely reporting to the Admiral of all threats and actions to identify and neutralize them.  During this assignment, I passed the Navy Command Qualification Examination and completed the qualification for Command.  One of my Human Resources Specialists was having trouble getting the Admiral\'s pay corrected.  I found the contacts aboard the Aircraft Carrier, at the Bureau of Naval Personnel, at the Defense Finance and Accounting Service, and coordinated dialogue between all of them to identify the administrative errors at the root of the Admiral\'s pay problem.  I smoothed relations between my Human Resources Staff and that of the Aircraft Carrier, and coordinated the efforts of all to fix the Admiral\'s pay and that of the rest of his staff of 75.", "company_name": "Commander Carrier Strike Group EIGHT", "last_updated": "2025-08-01T08:25:28.476341", "highest_level": "director", "sub_department": "", "company_linkedin_url": null}, {"title": "Director if Maritime Training and Mentorship", "company": "MINUSTAH", "end_date": "2015-05-01", "company_id": null, "department": "", "is_current": false, "start_date": "2014-05-01", "description": "International liaison on a multinational, multiservice staff of 21 different nationalities.  Coordinate with Haitian National Police (Coast Guard, Customs and Environmental), UN Police and MINUSTAH Staff for Maritime Security Operations and Training of the Haitian Coast Guard.  Wrote plans, policy documents and lessons learned reports and presentations.  Led six multinational, multiservice military Officers and Enlisted in Military Training for indoctrination, ongoing and non-routine training requirements of Haiti.  During my time in Haiti I finished the coursework for my second Masters in Strategy and International Studies through the U.S. Naval War College, and began studying for the Navy\'s Command Qualification Examination.", "company_name": "MINUSTAH", "last_updated": "2025-08-01T08:25:28.476341", "highest_level": "director", "sub_department": "", "company_linkedin_url": null}, {"title": "Director of Human Resources, Operations and International Security Training", "company": "Maritime Civil Affairs and Security Training Command", "end_date": "2014-04-01", "company_id": null, "department": "", "is_current": false, "start_date": "2013-08-01", "description": "Directed 20 Naval Officers and Chiefs in the management of 75 personnel.  Directed the planning and execution of international mobile training teams educating partner-nations in maritime security operations.  On short-notice of the organization’s disestablishment, I managed the production, proofing, editing, signature, and proper submission of 75 performance reviews and awards.  Worked closely with my managers and supervisors to produce a comprehensive procedure book for future Security Force Assistance detachments to use for their operations.", "company_name": "Maritime Civil Affairs and Security Training Command", "last_updated": "2025-08-01T08:25:28.476341", "highest_level": "director", "sub_department": "", "company_linkedin_url": null}, {"title": "Director Of Operations", "company": "Amphibious Squadron SIX", "end_date": "2013-06-01", "company_id": null, "department": "Operations", "is_current": false, "start_date": "2012-01-01", "description": "Managed schedules and plans for six ships and the staff. Managed the training, qualification, promotions, performance reviews, awards, and future employment assignments of 12 Officers and Sailors.  Coordinated four major operations with U.S. and Allied countries including Hurricane Sandy Disaster Relief.  Represented the Commodore at monthly meetings with the Fleet Commander’s staff.", "company_name": "Amphibious Squadron SIX", "last_updated": "2025-08-01T08:25:28.476341", "highest_level": "director", "sub_department": "", "company_linkedin_url": null}, {"title": "Director Of Operations", "company": "USS WHIDBEY ISLAND (LSD 41)", "end_date": "2011-12-01", "company_id": null, "department": "Operations", "is_current": false, "start_date": "2010-06-01", "description": "Managed 70 Sailors in 5 divisions in the operation, maintenance and repair of the ship\'s combat, communications, and navigation systems.  Singled out as the most prepared for each executive update, for certification and deployment", "company_name": "USS WHIDBEY ISLAND (LSD 41)", "last_updated": "2025-08-01T08:25:28.476341", "highest_level": "director", "sub_department": "", "company_linkedin_url": null}, {"title": "Training Liaison Officer", "company": "Afloat Training Group, Norfolk VA", "end_date": "2009-09-01", "company_id": null, "department": "Education", "is_current": false, "start_date": "2007-02-01", "description": "Coordinated assessments and training missions for 9 ships.  Liaised with Training Officers for the hiring/assignment, training and qualification of over 3000 Sailors for deployment.  Liaised between Staff members and 9 ships to ensure best quality of service and training value during Unit Level Training Phase.  During this assignment I worked after-hours to complete my Masters through Troy University, and began working on my second Masters through the Naval War College.  I discovered that the my organization had no way of answering the question \\"how are we doing,\\" from out customers, as we executed the routine package of drills and evaluations on them.  I worked with the head assessor of each of the 12 teams that I brought with me to ships, and developed a spreadsheet that took into consideration every point earned, lost, and still possible by the end of the ships\' assessment.  I was then able to use this spreadsheet to tell each ship Captain what was the best possible overall score that could be earned from each assessment, and differentiated between which areas needed to most work and attention, in order to bring the overall score up.  This spreadsheet was adopted by the organization, and incorporated into the program for every Training Liaison Officer to use.", "company_name": "Afloat Training Group, Norfolk VA", "last_updated": "2025-08-01T08:25:28.476341", "highest_level": "individual contributor", "sub_department": "Education_administration", "company_linkedin_url": null}, {"title": "Director of Operations", "company": "USS GUNSTON HALL (LSD 44) and others", "end_date": "2007-01-01", "company_id": null, "department": "Operations", "is_current": false, "start_date": "2005-04-01", "description": "Division Officer spot-promoted to Department Head.  Revitalized the department, managed the training, qualification, promotions, performance review, awards, and follow-on employment assignments of 60 Sailors, 10 Workcenters, 9 Warfare areas, 5 job fields, and 4 divisions in the operation and maintenance of all ship\'s combat, sensor, and communication equipment.  Mended lines of communication and authority.  Re-implemented sound procedures and standards for operations and performance.  Essembled, managed and executed all aspects of the ship\'s schedule.  Managed 4 Sailors in the liaison and coordination with shipyard and shipboard personnel for the successful completion of a depot level repairs of shipboard equipment.  Executive Assistant the the Chief Engineer in the management and administration of training, qualification, promotions, performance review, awards, and follow-on employment assignments of 75 Sailors, 6 job fields, and 4 divisions in the operation and maintenance of all ship\'s engineering plant and all auxiliary equipment.", "company_name": "USS GUNSTON HALL (LSD 44) and others", "last_updated": "2025-08-01T08:25:28.476341", "highest_level": "director", "sub_department": "", "company_linkedin_url": null}, {"title": "Manager of Repair Technicians and Human Resources Manager", "company": "USS Winston S. Churchill DDG 81", "end_date": "2005-04-01", "company_id": 1978042, "department": "", "is_current": false, "start_date": "2003-04-01", "description": "Managed the training, qualification, promotions, performance review, awards, and follow-on employment assignments of 6 Sailors in the proofing, editing, routing, and mailing of all correspondence, all pay, Human Resources, performance review, awards, training/qualification documentation, and follow-on employment/assignment of 300 Sailors.  Managed 12 Sailors in the operation and maintenance of radar, communications, hydraulics, and auxiliary engineering systems.  I was assigned to an organization which was responsible, in part, to close doors and valves, in order to stop the spread of fire and flooding throughout the ship.  My organization was notoriously the last one to complete this task, so I set out to fix it.  I spoke with the team of Sailors who actually closed the doors and valves, and they identified some points of confusion on the lists.  I took the lists to the senior assessor who evaluated my team\'s performance, and asked him if he would help me improve upon them by showing me the doors and valves on the lists, so I could better train my Sailors.  We discovered several incorrect letters and numbers of the doors and valves, and also that the order of the doors and valves on the lists was disorganized.  This meant that my Sailors were either running between different corners and floors of our area, or skipping past doors and valves that were out of order on the lists, to check them off later.  I found the electronic files, reorganized the doors and valves into a logical progression through the ship, corrected the erroneous designations, and gathered my Sailors for two training sessions including an untimed walk-through and a timed practice-run.  Every time after that, my organization was the first to be finished, and cut our time in half.", "company_name": "USS Winston S. Churchill DDG 81", "last_updated": "2025-08-01T08:25:28.476341", "highest_level": "manager", "sub_department": "", "company_linkedin_url": "https://www.linkedin.com/company/uss-winston-s.-churchill-ddg-81"}, {"title": "Office Manager and Human Resources Manager and YN1(SS) and Flag Administration Leading Yeoman", "company": "CINCLANTFLT (Now CFFC)", "end_date": "1999-07-01", "company_id": null, "department": "", "is_current": false, "start_date": "1997-01-01", "description": "Supervised 6 Sailors and Marines in proofing, editing, routing, and tracking of all correspondence, awards, messages, instructions, notices, personal letters, performance reviews, and anything else seen by either Admiral.  Supervised 3 Sailors in the administration of all qualifications, performance reviews, awards, and pay of two Admirals and their staff of 22 Officers, Sailors and Marines.  Recognized and sought out as the administration expert on a staff of over 1,000.  During this assignment I continued with my undergraduate education with Tidewater Community College.  I personally wrote a Staff Correspondence Manual, which listed all of the Admiral\'s preferences and specifications for technical writing packages, increasing speed and accuracy of all executive level correspondence.  A Sailor reported to my Staff, who could not get promoted.  He and I sat down together, looked over his provisional history, and I identified an area of his professional development that needed to be improved upon.  We made a plan and we made a deal to give him the time he needed to improve, and he got promoted on his next try.  I hope to do this for many others!", "company_name": "CINCLANTFLT (Now CFFC)", "last_updated": "2025-08-01T08:25:28.476341", "highest_level": "individual contributor", "sub_department": "", "company_linkedin_url": null}, {"title": "Human Resources Manager and Legal Clerk and YN1(SS)", "company": "COMSUBRON SIX", "end_date": "1996-12-01", "company_id": null, "department": "", "is_current": false, "start_date": "1995-05-01", "description": "Managed and administered separations and submarine disqualifications for all Sailors from 11 assigned submarines.  Managed and administered hiring, assignment, pay, benefits, performance review, and follow-on employment/assignment of over 1000 personnel in career transition status.  Identified hundreds of Sailors who were still being carried on our rolls, after having been transferred or discharged.  During this assignment, I began taking college courses from Tidewater Community College, and completed an apprenticeship as a Legal Secretary.  I compared reports from 3 different databases, as well as our historical files of personnel movements, and provided the right locational information to correct all deficiencies on our rolls.  This earned the first ever \\"Certified Pipeline Mover\\" award from the Bureau of Naval Personnel for proper management of transient personnel by our Staff.", "company_name": "COMSUBRON SIX", "last_updated": "2025-08-01T08:25:28.476341", "highest_level": "individual contributor", "sub_department": "", "company_linkedin_url": null}, {"title": "Human Resources Generalist and Office Clerk and YN2(SS)", "company": "USS FINBACK (SSN 670)", "end_date": "1995-05-01", "company_id": null, "department": "", "is_current": false, "start_date": "1993-03-01", "description": "Administered proofing, editing, routing, and mailing of all correspondence, all pay, Human Resources, performance reviews, awards, training/qualification documentation, and follow-on employment/assignment of 120 Sailors.  Pass Liaison Representative coordinating all pay, qualifications,  promotions, and documentation of professional history for 120 Sailors with the Human Resources team and the local Personnel Support Detachment.  I noticed significant shortfalls in our technical library of local and big Navy publications, used to manage and administer Navy programs on the ship.  I conducted research to identify the most current versions of each technical publication, incorporated required changes to some, and ordered over 100 others that were missing or outdated.  Our ship became the one with the most complete technical library in our Squadron.", "company_name": "USS FINBACK (SSN 670)", "last_updated": "2025-08-01T08:25:28.476341", "highest_level": "individual contributor", "sub_department": "", "company_linkedin_url": null}, {"title": "Human Resources Generalist and Office Clerk and YN3", "company": "USS EL PASO (LKA 117)", "end_date": "1993-01-01", "company_id": null, "department": "", "is_current": false, "start_date": "1990-11-01", "description": "Administered proofing, editing, routing, and mailing of all correspondence, all pay, Human Resources, performance review, awards, training/qualification documentation, and follow-on employment/assignment of 360 Sailors.  General Yeoman; service record entries, correspondence typing/editting/filing, customer service representative.", "company_name": "USS EL PASO (LKA 117)", "last_updated": "2025-08-01T08:25:28.476341", "highest_level": "individual contributor", "sub_department": "", "company_linkedin_url": null}]', '[{"end": 2018, "major": "Lean Six Sigma", "start": 2018, "degree": "Green Belt", "school": "Navy Expeditionary Combat Command"}, {"end": 2018, "major": "Human Resources", "start": 2018, "degree": "Senior Professional in Human Resources", "school": "Syracuse University"}, {"end": 2015, "major": "Management Science with Human Resources focus", "start": 2007, "degree": "Master\'s degree", "school": "Troy University"}, {"end": 2014, "major": "African History and International Relations and National Security Studies", "start": 2008, "degree": "Master of Arts in National Security and Strategic Studies", "school": "Naval War College"}, {"end": 2002, "major": "Business Administration and Management, General", "start": 1999, "degree": "Bachelor of Science (B.S.) SUMMA CUM LAUDE", "school": "Strome College of Business"}, {"end": 1999, "major": "Computer Science", "start": 1995, "degree": "37 Credits", "school": "Tidewater Community College"}]', '[]', '[]', '{"id": 58122977, "tags": [{"id": 25493700, "name": "API Contacts"}], "links": {"facebook": "https://facebook.com/joseph.j.johansen", "linkedin": "https://www.linkedin.com/in/josephjjohansen"}, "npi_data": null, "profile_list": {"id": 29016828, "name": "API Contacts"}, "region_latitude": 36.8529263, "region_longitude": -75.977985, "current_work_email": null, "current_personal_email": "josephjjohansen@live.com"}', null, null, null, '2025-09-10 13:21:17', '2025-09-10 13:21:17', null);
INSERT INTO `marine-db`.stakeholders (id, vessel_id, company_id, searched_company_id, name, role, personal_email, professional_email, linkedin_url, status, profile_pic, location, city, region, country, country_code, birth_year, current_employer, current_employer_id, current_employer_domain, current_employer_website, current_employer_linkedin_url, recommended_email, emails_json, phones_json, job_history_json, education_json, skills_json, company_json, others_data, created_by, updated_by, deleted_by, created_at, updated_at, deleted_at) VALUES (225, null, 172, 172, 'Susan Jackson', 'Purchasing Agent', 'susanjackson92872@gmail.com', null, 'https://www.linkedin.com/in/susan-jackson-8938863b', 'progress', 'https://d2gjqh9j26unp0.cloudfront.net/profilepic/e9025f056cf7125984398d09f5dca0cf', 'United States', null, '', 'United States', 'US', 1974, 'USMMI (US MARINE MANAGEMENT, LLC)', null, null, null, null, 'susanjackson92872@gmail.com', '[{"type": "personal", "email": "susanjackson92872@gmail.com", "grade": "A", "smtp_valid": "valid", "last_validation_check": "2025-09-03"}]', '[]', '[{"title": "Purchasing Agent", "company": "USMMI (US MARINE MANAGEMENT, LLC)", "end_date": "Present", "company_id": null, "department": "Operations", "is_current": true, "start_date": "2023-09-01", "description": "", "company_name": "USMMI (US MARINE MANAGEMENT, LLC)", "last_updated": "2025-09-06T05:53:54.753738", "highest_level": "individual contributor", "sub_department": "Supply_chain", "company_linkedin_url": null}, {"title": "Purchasing Agent - Government Procurement - Services - T-AKR, TAGOS, MPF and TAGS ships", "company": "Maersk Line Limited, Norfolk VA", "end_date": "Present", "company_id": null, "department": "", "is_current": false, "start_date": "2014-03-01", "description": "•\\tA dedicated Purchasing Agent for the T-AGOS , MPF , TAGS and currently the T-AKR vessel contracts, Ms. Jackson is responsible for repair-related procurement services in support of the MILITARY Sealift Command Navy ships fleet. •\\tManages all phases of contract administration for Regular Overhaul (ROH) and Industrial Assistant Service orders to include soliciting, evaluating, negotiating and awarding contracts, assuring compliance with terms and conditions of contracts, resolution of problems, through contract close out. •\\tDirects all subcontract negotiations including consent requirements, Price Negotiation Memorandums, analyzing and evaluating cost or price proposals,  Final Proposal Revision (FPR)/BAFO analysis and ensuring that mission needs are being met within budget and in compliance with all applicable regulations and Federal socioeconomic goals. •\\tDevelops acquisition strategies and manages all service components involved with Material Readiness Availability port calls and Regular Overhaul Dry Dockings. •\\tEstablishes and maintains strong industry relationships to enhance cross functional cooperation with both US and overseas vendors. •\\tManages vendor progress, including any performance mitigation issues that may impact mission needs or vessel departure.", "company_name": "Maersk Line Limited, Norfolk VA", "last_updated": "2025-09-06T05:53:54.753738", "highest_level": "individual contributor", "sub_department": "", "company_linkedin_url": null}]', '[{"end": 2003, "major": "MBA", "start": 2000, "degree": "MBA", "school": "Averett University"}, {"end": 1996, "major": "Environmental Sciences", "start": 1992, "degree": "BS", "school": "Lynchburg College"}, {"end": null, "major": "Environmental Science", "start": null, "degree": "Bachelor\'s degree", "school": "University of Lynchburg"}]', '["Proposal Writing", "Government", "Logistics", "Government Procurement", "Management", "Procurement", "Security Clearance", "Contract Management", "Purchasing", "Supply Chain Management", "Government Contracting", "Strategic Sourcing", "Negotiation", "Administration", "Logistics Management", "Pricing", "Supply Management", "Materials Management", "Supply Chain", "Contract Negotiation", "Operations Management", "Supply", "Social Media", "Project Management", "Microsoft Excel", "HR", "Microsoft Word", "Marketing", "Finance"]', '[]', '{"id": 41657748, "tags": [{"id": 25493700, "name": "API Contacts"}], "links": {"facebook": "https://facebook.com/susanrobey", "linkedin": "https://www.linkedin.com/in/susan-jackson-8938863b"}, "npi_data": null, "profile_list": {"id": 29016828, "name": "API Contacts"}, "region_latitude": 37.09024, "region_longitude": -95.712891, "current_work_email": null, "current_personal_email": "susanjackson92872@gmail.com"}', null, null, null, '2025-09-10 13:21:47', '2025-09-10 13:21:47', null);
INSERT INTO `marine-db`.stakeholders (id, vessel_id, company_id, searched_company_id, name, role, personal_email, professional_email, linkedin_url, status, profile_pic, location, city, region, country, country_code, birth_year, current_employer, current_employer_id, current_employer_domain, current_employer_website, current_employer_linkedin_url, recommended_email, emails_json, phones_json, job_history_json, education_json, skills_json, company_json, others_data, created_by, updated_by, deleted_by, created_at, updated_at, deleted_at) VALUES (226, null, 172, 172, 'Elizabeth Womack', 'Purchasing Agent', null, 'ewomack@usmmi.com', 'https://www.linkedin.com/in/elizabethsjwomack', 'progress', 'https://d2gjqh9j26unp0.cloudfront.net/profilepic/b4c1be5d5f9de1b99abc870a2d32152a', 'Virginia Beach, VA, US', 'Virginia Beach', 'VA', 'United States', 'US', 1989, 'U.S. Marine Management (USMMI)', 50292892, 'usmmi.com', 'https://www.usmmi.com/', 'https://www.linkedin.com/company/u-s-marine-management', 'ewomack@usmmi.com', '[{"type": "professional", "email": "ewomack@usmmi.com", "grade": "A", "smtp_valid": "valid", "last_validation_check": "2025-08-03"}, {"type": "professional", "email": "elizabethwomack@usmmi.com", "grade": "F", "smtp_valid": "invalid", "last_validation_check": "2025-08-03"}, {"type": "professional", "email": "elizabethw@usmmi.com", "grade": "F", "smtp_valid": "invalid", "last_validation_check": "2025-08-03"}, {"type": "professional", "email": "elizabeth.womack@usmmi.com", "grade": "F", "smtp_valid": "invalid", "last_validation_check": "2025-08-03"}, {"type": "personal", "email": "elizabethsuzannejefferis@yahoo.com", "grade": "F", "smtp_valid": "invalid", "last_validation_check": "2025-08-03"}]', '[]', '[{"title": "Purchasing Agent", "company": "U.S. Marine Management (USMMI)", "end_date": "Present", "company_id": 50292892, "department": "Operations", "is_current": true, "start_date": "2018-10-01", "description": "- Receive and review purchase requests as assigned. - Select sources of supply - Negotiate and place orders/contracts with qualified sources - Monitor all orders/contracts from placement to completion, and reconcile problems. - Communicate with vessels, company agents, and technical operations via written and oral correspondence - Ensure that all federal Acquisition Regulation (FAR) requirements are adhered to - Input purchase order information to the purchasing computer system - Perform such research as necessary to develop new/alternate sources of supply - Responsible for compliance with all ISO 9000 procedures applicable to Purchasing - Negotiates pricing terms and conditions - Responsible for independent purchase authority up to $75,000.00 - Supports commitment to safety and other selected company standards and certifications - Assists with and writes SOPs for ROH, APACS, and IATP processes.", "company_name": "U.S. Marine Management (USMMI)", "last_updated": "2025-07-31T00:19:28.826977", "highest_level": "individual contributor", "sub_department": "Supply_chain", "company_linkedin_url": "https://www.linkedin.com/company/u-s-marine-management"}, {"title": "Logistics Coordinator - Freight Broker - Dispatch", "company": "Commodity Distribution, Inc.", "end_date": "2018-10-01", "company_id": null, "department": "", "is_current": false, "start_date": "2015-01-01", "description": "- Granted 2015’s Administrative Employee of the Year award prior to a full year’s employment - Created & maintained a personal manual of job processes & responsibilities which was requested by management to be utilized to in the training of coworkers on job responsibilities, changes to currently used systems, & implementation of new practices - Spearheaded utilization of new broker-carrier contract & shift to a digitized confirmation delivery method; reformed hard copy filing systems to support changes - Collected, organized, & managed  preparation of documents for IRS audit Independently, & collaboratively, reworked & maintained accuracy of various documents for simplicity, understanding, & addition of new information/requirements including a contractual agreement resulting in decreased paper usage, reducing supply costs & company’s carbon footprint - Trained new & current employees on job duties, procedural modifications, updates to frequently used programs, & shifts in regulations - Maintained integrity & organization of tasks & paperwork, through dispatching programs like PCS Software, online based portals, internal shared documents, & hard copy filing systems - Collected & verified various documents such as completed contracts & insurance certificates to secure partnerships, protect the interests of the company, & prevent insurance fraud - Created & accurately maintained carrier, customer, shipper & receiver profiles Initiated the transportation of various commodities through communication with established drivers/dispatchers, & utilization of resources such as online load boards to source new carriers. - Set, negotiated, & updated rates based on current market trends, fuel costs, demand, & urgency - Researched efficient & cost-effective routes to ensure on-time delivery while mitigating losses through problem prevention, load monitoring, & load recovery - Met with local logistics community members to build new & foster existing relationships", "company_name": "Commodity Distribution, Inc.", "last_updated": "2025-07-31T00:19:28.826977", "highest_level": "individual contributor", "sub_department": "", "company_linkedin_url": null}, {"title": "Export Booking Representative", "company": "CMA CGM", "end_date": "2015-01-01", "company_id": 8050, "department": "Sales", "is_current": false, "start_date": "2014-06-01", "description": "- Collected customer information via multiline telephone and email to schedule new bookings and enter into internal company system - Edited existing bookings to meet customer specific requirements, company standards, and updated information as received - Confirmed correct contact information and contract to ensure correct invoice parties and amounts - Collaborated with other departments to ensure all aspects of shipments properly coordinated, equipment available, and documents received - Followed-up with customers to inform of canceled, amended, or date-shifted bookings", "company_name": "CMA CGM", "last_updated": "2025-07-31T00:19:28.826977", "highest_level": "individual contributor", "sub_department": "Sales_operations", "company_linkedin_url": "https://www.linkedin.com/company/cma-cgm"}, {"title": "Inbound Vessel Close Coordinator", "company": "US Lines", "end_date": "2014-06-01", "company_id": 41696444, "department": "Operations", "is_current": false, "start_date": "2013-08-01", "description": "(Left due to outsourcing. Subsidiary of CMA-CGM, America) - Ran and examined reports to ensure accurate release of cargo to appropriate parties through use of internal company systems and external terminal websites - Monitored of assigned services to ensure receipt of payments, necessary documentation, and clearances - Confirmed contact information to ensure invoices and arrival notices sent rated or unrated to the correct parties - Communicated with overseas agents and domestic departments to coordinate shipments - Assured timely transmission of information to terminals, internal and external departments, and customers - Independently monitored assigned services and assisted with coworker workloads as needed - Prepared files for claims of cargo not fully released - Prioritized tasks and time to accommodate deadlines for assigned services", "company_name": "US Lines", "last_updated": "2025-07-31T00:19:28.826977", "highest_level": "individual contributor", "sub_department": "Logistics", "company_linkedin_url": "https://www.linkedin.com/company/uslines"}, {"title": "Export Documentation Coordinator", "company": "CMA CGM", "end_date": "2013-08-01", "company_id": 8050, "department": "Operations", "is_current": false, "start_date": "2012-08-01", "description": "(Left due to outsourcing) - Produced accurate bills of lading as per company, port, and U.S. Customs regulations with use of Microsoft and other applications (Excel, Word, PowerPoint, Outlook, Internet Explorer, Mozilla, Adobe Reader) - Collected and reviewed documentation from customers to ensure accurate and complete information - Transcribed information accurately and efficiently into internal system preventing miscommunication and unnecessary costs to company - Communicated with customers via telephone and email to ensure all information complete and correct - Adhered to all rules, regulations, and procedures as defined by the global and domestic company branches", "company_name": "CMA CGM", "last_updated": "2025-07-31T00:19:28.826977", "highest_level": "individual contributor", "sub_department": "Logistics", "company_linkedin_url": "https://www.linkedin.com/company/cma-cgm"}, {"title": "Head Cashier", "company": "Barnes & Noble, Inc.", "end_date": "2012-08-01", "company_id": 4417, "department": "Operations", "is_current": false, "start_date": "2012-07-01", "description": "In addition to general Bookseller duties: - Maintained front-of-store displays with regards to sales and promotions - Processed returns and exchanges as well as purchase transactions - Trained Booksellers at the checkout to process transactions - Alleviated adverse customer situations and issues", "company_name": "Barnes & Noble, Inc.", "last_updated": "2025-07-31T00:19:28.826977", "highest_level": "head", "sub_department": "Office_management", "company_linkedin_url": "https://www.linkedin.com/company/barnes-&-noble"}, {"title": "Bookseller", "company": "Barnes & Noble, Inc.", "end_date": "2012-06-01", "company_id": 4417, "department": "", "is_current": false, "start_date": "2007-05-01", "description": "- Assisted customers in locating, ordering, and purchasing merchandise via face-to-face interactions, telephone conversations, and website requests - Maintained inventory through review, organization, and replenishment - Nook Smart certified; guided customers in the use of the Barnes & Noble website, phone app, and nook e-reader products", "company_name": "Barnes & Noble, Inc.", "last_updated": "2025-07-31T00:19:28.826977", "highest_level": "individual contributor", "sub_department": "", "company_linkedin_url": "https://www.linkedin.com/company/barnes-&-noble"}, {"title": "Hostess and Trainer", "company": "Red Robin", "end_date": "2007-04-01", "company_id": 9516347, "department": "", "is_current": false, "start_date": "2006-04-01", "description": "- Trained new hostesses as a Certified Designated Trainer (CDT) - Evaluated servers according to store standards - Supervised and directed hostess staff - Exemplified time management abilities by assisting wait staff during peak business periods while performing hostess and supervisor duties", "company_name": "Red Robin", "last_updated": "2025-07-31T00:19:28.826977", "highest_level": "individual contributor", "sub_department": "", "company_linkedin_url": "https://www.linkedin.com/company/red-robin-gourmet-burgers"}, {"title": "Volunteer", "company": "Kempsville Area Public Library", "end_date": "2007-02-01", "company_id": null, "department": "", "is_current": false, "start_date": "2005-03-01", "description": "- Organized returned books and media - Assisted adults and children with completion of summer reading program forms -Worked independently to create new library card packets and organize books to be shipped to other branches", "company_name": "Kempsville Area Public Library", "last_updated": "2025-07-31T00:19:28.826977", "highest_level": "unpaid", "sub_department": "", "company_linkedin_url": null}]', '[{"end": 2023, "major": "Graphic Design and Business", "start": 2023, "degree": "Course Completion", "school": "Bonnie Christine: The Surface Design Immersion Course"}, {"end": 2012, "major": "Communications", "start": 2009, "degree": "Bachelor of Arts (B.A.)", "school": "Old Dominion Universit