: "Victim advocate for sexual assault and harrasament, domestic violence, and suicide", "start": 2018, "degree": "Nationally Certified Victim Advocate", "school": "National Advocate Credentialing Program"}, {"end": null, "major": "Crisis/Emergency/Disaster Management", "start": 2023, "degree": "Master of Business Administration - MBA", "school": "American Military University"}]', '["Recruiting", "Contract Negotiation", "Contract Management", "Procurement", "Leadership", "Safety Regulations", "Safety Audits", "Occupational Safety", "Relationship Development", "Management", "Project Plans", "Program Development", "Operational Risk Management", "Risk Management", "Risk Assessment", "OSHA", "Hazardous Materials", "Fire Safety", "Occupational Health", "Policy Writing", "Operational Planning", "Training & Development", "Emergency Planning", "Disaster Response", "Emergency Management", "Emergency Services", "Public Safety", "Environment, Health, and Safety (EHS)", "Workplace Safety", "Organizational Leadership", "Event Planning", "Customer Relationship Management (CRM)", "Sales & Marketing", "Logistics Management", "Microsoft Excel", "Salesforce.com", "Microsoft Word", "Microsoft PowerPoint", "Microsoft Project", "Skilled Multi-tasker", "Interpersonal Communication", "Problem Solving", "Budget Analysis", "Veterans Affairs", "Organizational Psychology", "Sponsorship Management", "Marketing Event Planning", "Package Client Management", "Client Communication Oversight", "Team Coordinator of Client Outreach"]', '{"error": "Insufficient balance for company lookup"}', '{"id": 748755244, "tags": [{"id": 25493700, "name": "API Contacts"}], "links": {"linkedin": "https://www.linkedin.com/in/jordan-dhereaux-csm-53223117a"}, "npi_data": null, "profile_list": {"id": 29016828, "name": "API Contacts"}, "region_latitude": 36.7682088, "region_longitude": -76.2874927, "current_work_email": "jdhereaux@usmmi.com", "current_personal_email": "jordandhereaux@gmail.com"}', null, null, null, '202