rl": "https://www.linkedin.com/company/u-s-marine-management"}, {"title": "Executive Assistant", "company": "U.S. Coast Guard", "end_date": "2024-06-01", "company_id": 4425, "department": "Operations", "is_current": false, "start_date": "2022-06-01", "description": "Served as Front Office Chief of Staff to C-Suite level equivalent executive in the coordination/integration/synchronization of staff actions, events, & activities across eleven offices with a $32M annual operating budget. Lead Coast Guard Directorate for vessel, facility, and waterways management policy for domestic/international regulatory compliance, physical safety/security, cyber security, and auditing of third-party organizations. Coordinated external affairs, Congressional engagements, and strategic planning to execute agency goals across the interagency & national/international stakeholders.", "company_name": "U.S. Coast Guard", "last_updated": "2025-07-21T03:04:37.073783", "highest_level": "individual contributor", "sub_department": "Corporate_strategy", "company_linkedin_url": "https://www.linkedin.com/company/uscoastguard"}, {"title": "Senior Manager (Prevention Department Head)", "company": "U.S. Coast Guard", "end_date": "2022-06-01", "company_id": 4425, "department": "", "is_current": false, "start_date": "2019-06-01", "description": "Led Marine Safety Unit Houma’s mission to exercise Coast Guard authorities across the marine transportation system. Directly supervised over ninety active duty and civilian personnel conducting field operations in vessel compliance, facility compliance, casualty investigations and waterways management. Fostered collaborative partnerships with port executives, domestic/international vessel owners/management and facility operators with a concentration in the oil and gas industry. Guided the Coast Guard’s largest towing vessel fleet of responsibility in transitioning to Subchapter M compliance. Key leader and Incident Command System Operations Section Chief for the interagency response to the direct effects of Hurricane Ida on South Louisiana.", "company_name": "U.S. Coast Guard", "last_updated": "2025-07-21T03:04:37.073783", "highest_level": "manager", "sub_department": "", "company_linkedin_url": "https://www.linkedin.com/company/uscoastguard"}, {"title": "Safety and Environmental Health Officer", "company": "U.S. Coast Guard", "end_date": "2019-06-01", "company_id": 4425, "department": "Operations", "is_current": false, "start_date": "2016-05-01", "description": "Provided occupational safety, industrial hygiene and environmental health support to over one-hundred units representing all Coast Guard operational missions in the state of California. Designed and published study on law enforcement personnel exposure to fentanyl that was shared with partner law enforcement agencies and supported changes in Coast Guard policy on personal protective measures for law enforcement teams. Deployed as ICS Type II Safety Officer for Hurricanes Harvey, Irma, Maria and Florence.", "company_name": "U.S. Coast Guard", "last_updated": "2025-07-21T03:04:37.073783", "highest_level": "individual contributor", "sub_department": "Quality_management", "company_linkedin_url": "https://www.linkedin.com/company/uscoastguard"}, {"title": "Graduate Student", "company": "The University of Texas Health Science Center at Houston (UTHealth)", "end_date": "2016-05-01", "company_id": 215953, "department": "", "is_current": false, "start_date": "2014-08-01", "description": "Graduate Student, MPH-Industrial Hygiene", "company_name": "The University of Texas Health Science Center at Houston (UTHealth)", "last_updated": "2025-07-21T03:04:37.073783", "highest_level": "training", "sub_department": "", "company_linkedin_url": "https://www.linkedin.com/company/uthealthschoolofpublichealth"}, {"title": "Coast Guard Officer", "company": "U.S. Coast Guard", "end_date": "2014-06-01", "company_id": 4425, "department": "", "is_current": false, "start_date": "2003-11-01", "description": "2011 - 2014: Division Chief for domestic and foreign vessel inspections in the Marine Safety Unit Savannah area of responsibility to include the third busiest container port in the United States. 2010 - 2011: Detached duty assignment to the U.S. Army’s 1st Infantry Division in Basra Province, Iraq. Advised and assisted the Government of Iraq in improving port facility security and infrastructure. Credentialed delegate for the country of Iraq to the International Maritime Organization, Maritime Safety Committee’s 89th Session in London. 2007 - 2010: Division Chief for marine casualty and mariner investigations across the Coast Guard’s District 8 twenty six-state area of responsibility. Participant and Coast Guard investigations policy representative to the Towing Vessel Safety Advisory Committee during the initial phase in of towing vessel inspections. Partnered with the Passenger Vessel Association and local law enforcement to address mariner licensing and drug testing compliance for illegal passenger vessel operations on inland lakes. 2003 - 2007: Apprentice Marine Inspector and Marine Casualty Investigator. Oversaw new construction projects for vessels engaged primarily in the oil and gas industry. Lead Investigating Officer presenting mariner misconduct cases before an Administrative Law Judge for adjudication. Conducted evacuation and law enforcement operations in New Orleans during the aftermath of Hurricanes Katrina and Rita.", "company_name": "U.S. Coast Guard", "last_updated": "2025-07-21T03:04:37.073783", "highest_level": "individual contributor", "sub_department": "", "company_linkedin_url": "https://www.linkedin.com/company/uscoastguard"}]', '[{"end": 2016, "major": "Industrial Hygiene", "start": 2014, "degree": "Master of Public Health (MPH)", "school": "The University of Texas Health Science Center at Houston"}, {"end": 2006, "major": "Coastal Zone Management", "start": 2006, "degree": null, "school": "Nova Southeastern University"}, {"