m/company/seanergy-maritime-holdings-corp-"}, {"title": "Fleet Superintendent", "company": "V.Group", "end_date": "2025-02-01", "company_id": 39522338, "department": "Operations", "is_current": false, "start_date": "2021-11-01", "description": "", "company_name": "V.Group", "last_updated": "2025-04-07T04:05:22.211689", "highest_level": "manager", "sub_department": "Logistics", "company_linkedin_url": "https://www.linkedin.com/company/vgroupmaritime"}, {"title": "Technical Dept", "company": "Capital Ship Management Corp.", "end_date": "2021-10-01", "company_id": 408615, "department": "Engineering", "is_current": false, "start_date": "2019-10-01", "description": "", "company_name": "Capital Ship Management Corp.", "last_updated": "2025-04-07T04:05:22.211689", "highest_level": "individual contributor", "sub_department": "", "company_linkedin_url": "https://www.linkedin.com/company/capital-ship-management"}, {"title": "Marine Engineer", "company": "Polembros Shipping", "end_date": "2019-09-01", "company_id": 5342984, "department": "Engineering", "is_current": false, "start_date": "2017-08-01", "description": "18 Months seagoing expierience in crude oil tankers Performed all engineering duties aboard ship. Gained a thorough knowledge of equipment maintenance and operation assisting in all engineering related tasks. Participated in watch keeping requirements. Filled out the Engine logbook daily in a timely manner. Participated in all safety meetings and drills. Fully familiarized with ISM Code, MARPOL Regulations, TMSA 3 & Class Requirements, IMPA Code", "company_name": "Polembros Shipping", "last_updated": "2025-04-07T04:05:22.211689", "highest_level": "individual contributor", "sub_department": "", "company_linkedin_url": "https://www.linkedin.com/company/polembros"}, {"title": "Sales Engineer", "company": "TheodoridesBros S.A", "end_date": "2017-08-01", "company_id": null, "department": "Sales", "is_current": false, "start_date": "2012-09-01", "description": "-SKUs demand forecasting by correcting the forecasts from the sales data. -Responsible to maintain the customer base, to prepare the Quotations for the Requests for Proposal (RFPs), and to adjust the discounts for the customers.", "company_name": "TheodoridesBros S.A", "last_updated": "2025-04-07T04:05:22.211689", "highest_level": "individual contributor", "sub_department": "Business_development", "company_linkedin_url": null}, {"title": "Inventory and Procurement Planner", "company": "TheodoridesBros S.A", "end_date": "2013-11-01", "company_id": null, "department": "Operations", "is_current": false, "start_date": "2011-06-01", "description": "-Responsible for the procurement of SKUs to be imported from Spain, Italy and Bulgaria, China. -Implementation of inventory management techniques (EOQ, Single Period Models, etc.) to optimize the Inventory Levels for 400 SKUs. -Lowered the Inventory level by ~25% to absorb the dramatic decrease of accounts payable, due to the credit terms imposed by suppliers in Greek businesses.", "company_name": "TheodoridesBros S.A", "last_updated": "2025-04-07T04:05:22.211689", "highest_level": "individual contributor", "sub_department": "Supply_chain", "company_linkedin_url": null}, {"title": "Diploma Thesis", "company": "TheodoridesBros S.A", "end_date": "2011-05-01", "company_id": null, "department": "", "is_current": false, "start_date": "2011-02-01", "description": "The dissertation was carried out aiming at the development of the forecast of demand in the import and trade company of industrial hydraulic equipment. First there was the process of classification based on the criteria of the annual value of usage and annual value of demand. Later the codes were graded based on the imports value as well as the average stock value, so that it could be checked whether codes with a high gathering in deposit are kept. The codes which proved to be critical according to the classification based on the annual value of the demand were used so that that the model of forecast could be developed. For the smoothing of the demand data the models of the simple moving average, the simple exponential smoothing, the model of the double exponential smoothing, the exponential smoothing adapted to the trend and the exponential smoothing adapted to the trend and the seasonal demand were used. Finally, regarding those codes as well as the prices of the demand per year which will arise, will calculate the optimal reorder portions and frequency of orders.", "company_name": "TheodoridesBros S.A", "last_updated": "2025-04-07T04:05:22.211689", "highest_level": "individual contributor", "sub_department": "", "company_linkedin_url": null}]', '[{"end": 2012, "major": "Mechanical Engineering", "start": 2005, "degree": "Master of Engineering (M.Eng.)", "school": "National Technical University of Athens"}]', '[]', '{"error": "Insufficient balance for company lookup"}', '{"id": 124558968, "tags": [{"id": 25493700, "name": "API Contacts"}], "links": {"linkedin": "https://www.linkedin.com/in/charalampostheodoridis"}, "npi_data": null, "profile_list": {"id": 29016828, "name": "API Contacts"}, "region_latitude": 37.9429857, "region_longitude": 23.6469832, "current_work_email": null, "current_personal_email": null}', null, null, null, '2025-09-13 18:26:36', '2025-09-13 18:26:36', null);
