INSERT INTO `marine-db`.stakeholders (id, vessel_id, company_id, searched_company_id, name, role, personal_email, professional_email, linkedin_url, status, profile_pic, location, city, region, country, country_code, birth_year, current_employer, current_employer_id, current_employer_domain, current_employer_website, current_employer_linkedin_url, recommended_email, emails_json, phones_json, job_history_json, education_json, skills_json, company_json, others_data, created_by, updated_by, deleted_by, created_at, updated_at, deleted_at) VALUES (257, 122, 193, 193, 'Novendi Ichwan', 'Logistics and Purchasing', 'nov.ive@gmail.com', null, 'https://www.linkedin.com/in/novendi-ichwan-~-ive-8a41b824', 'progress', 'https://d1hbpr09pwz0sk.cloudfront.net/profile_pic/novendi-ichwan-ive-30cc10b8', 'Surabaya, ID', 'Surabaya', '', 'Indonesia', 'ID', 1981, 'PT. Tanto Intim Line', null, null, null, null, 'nov.ive@gmail.com', '[{"type": "personal", "email": "nov.ive@gmail.com", "grade": "A", "smtp_valid": "valid", "last_validation_check": "2025-05-19"}, {"type": "personal", "email": "ive_nov@yahoo.com", "grade": "F", "smtp_valid": "invalid", "last_validation_check": "2025-05-19"}]', '[]', '[{"title": "Logistics and Purchasing", "company": "PT. Tanto Intim Line", "end_date": "Present", "company_id": null, "department": "Operations", "is_current": true, "start_date": "2014-06-01", "description": "To manage and control the purchase of goods and provision of high quality services at reasonable prices, to meet the needs of the company. Responsible for all purchasing activities. Arrange shipping and warehouse inventory control. Coordinate with vendors and logistics department for the delivery process procedures.", "company_name": "PT. Tanto Intim Line", "last_updated": "2025-05-02T03:37:00.293313", "highest_level": "individual contributor", "sub_department": "Logistics", "company_linkedin_url": null}, {"title": "Technical Purchaser", "company": "PT. Tanto Intim Line", "end_date": "Present", "company_id": null, "department": "Operations", "is_current": false, "start_date": "2014-02-01", "description": "1.\\tEnsure an optimal supply process according to the requirements of products ordered from all the vessel. 2.\\tMaintain records of goods ordered and received. 3.\\tPrepare and process requisitions and purchase orders for supplies and equipment. 4.\\tReview purchase order claims and contracts for conformance to company policy. 5.\\tAnalyze market and delivery systems in order to assess present and future material availability. 6.\\tDevelop and implement purchasing and contract management instructions, policies, and procedures. 7.\\tParticipate in the development of specifications for equipment, products or substitute materials. 8.\\tAdminister on-line purchasing systems. 9.\\tArrange for disposal of surplus materials. 10.\\tIdentify prospective manufacturers / suppliers for the purchase of machinery, equipment , materials and spare parts required by domestic orders issued by the applicant; 11.\\tManage the relation with the applicant and the purchase order approvers to resolve details concerning -specifications, quantities, price, quantity, lead-time and descriptions. 12.\\tPlan the procurement operations. 13.\\tPrepare and calls for proposals. 14.\\tForward offers from suppliers for technical approval by the applicant. 15.\\tAnalyze the suppliers’ offers according to the commercial point of view (price, delivery date and payment type. 16.\\tTransmit the order to the supplier and follow up the orders until goods receipt. 17.\\tMaintain properly organized records, files and reports for efficient, complete, timely and accurate referencing, as required by purchasing procedures. 18.\\tEnsure the compliance of the terms and conditions with orders. 19.\\tClarify with supplier any possible/ occurred non conformities (quantity and/or quality. 20.\\tTrack and control excess and obsolete stock, provide and coordinate actions plans. 21.\\tUpdate and process price, supplier contact information and delivery changes on the ERP database for all assigned items.", "company_name": "PT. Tanto Intim Line", "last_updated": "2025-05-02T03:37:00.293313", "highest_level": "individual contributor", "sub_department": "Supply_chain", "company_linkedin_url": null}, {"title": "Project Officer and Site Manager", "company": "PT. Dok dan Perkapalan Surabaya", "end_date": "2014-02-01", "company_id": null, "department": "", "is_current": false, "start_date": "2007-03-01", "description": "In New Ship Building of Pertamina Tanker Project at PT. Dok Perkapalan Surabaya Planned activities include work time, quality requirements, work result, performance, diagnosis mismatches. Coordinate project work related to the implementation and coordination with other relevant department of the smooth implementation of Tanker Pertamina 6500 LTDW Project. Implement the goals and programs of work portion of the project, and consistent with all relevant regulations comply with the standards and concepts of organizational work. Applying quality procedures in all work activities for the improved performance of the organization and implementation of quality procedures to handle constraints and implement workflow (input, still process and output) and the linkage function is its role with others department in the company. Planning activities in carrying out the duties and responsibilities of the position as well as the steps needed, and convey information to others both orally and in writing in a timely. Establish a solid working team, focused and measurable work in achieving the specified targets, handling problems that arise in the process of team solidarity quickly and accurately, Influence, persuade and move others to work with passion. Convey information orally and in writing in a work report accurately, systematically and timely. Work plan and mobilization of personnel for the execution of the work project control. Plan and mobilize resources for the implementation of equipment and facilities maintenance work that is the responsibility of each user.", "company_name": "PT. Dok dan Perkapalan Surabaya", "last_updated": "2025-05-02T03:37:00.293313", "highest_level": "individual contributor", "sub_department": "", "company_linkedin_url": null}, {"title": "Drafter of Electricity Panel and CNC programming", "company": "PT. Metro Abdibina sentosa Surabaya", "end_date": "2007-03-01", "company_id": null, "department": "Engineering", "is_current": false, "start_date": "2003-03-01", "description": "-\\tDesign and drafting of electricity box panel include design of wiring control electricity. -\\tDesign and programming CNC punching of electric box panel.", "company_name": "PT. Metro Abdibina sentosa Surabaya", "last_updated": "2025-05-02T03:37:00.293313", "highest_level": "individual contributor", "sub_department": "Electrical", "company_linkedin_url": null}]', '[{"end": 2010, "major": "marine", "start": 2008, "degree": "S1", "school": "Institute technology adhi tama surabaya"}, {"end": 2002, "major": "Marine", "start": 1999, "degree": "Diploma", "school": "Institut Teknologi Sepuluh November"}]', '[]', '[]', '{"id": 92879137, "tags": [{"id": 25493700, "name": "API Contacts"}], "links": {"linkedin": "https://www.linkedin.com/in/novendi-ichwan-~-ive-8a41b824"}, "npi_data": null, "profile_list": {"id": 29016828, "name": "API Contacts"}, "region_latitude": -7.2574719, "region_longitude": 112.7520883, "current_work_email": null, "current_personal_email": "nov.ive@gmail.com"}', null, null, null, '2025-09-13 18:27:17', '2025-09-13 18:27:17', null);
